async function getOrder(id: string): Promise<Order> {
  const resp = await axios.get(`/orders/${id}`);
  return resp.data as Order;
}

async function createOrder(req: CreateOrderRequest): Promise<OrderSummary> {
  const resp = await axios.post('/orders', req);
  return resp.data;
}

interface Order {
  id: number;
  price: number;
  description: string;
}

interface OrderSummary {
  id: number;
  status: string;
}
